المقارنة بين المتغيرات المنطقية المتفرقة وآلة الحالة المحكمة:
```kotlin
// ❌ فوضى الـ Scattered Booleans: احتمالية ظهور حالات مستحيلة وغير قانونية:
class BadCheckoutViewModel : ViewModel() {
    var isLoading = false
    var isPaid = false
    var hasError = false

    fun pay() {
        isLoading = true
        // لو حصل Exception وسقط الكود، قد يظل isLoading = true مع hasError = true!
    }
}

// ✅ آلة حالة صريحة (Explicit State Machine) باستخدام Sealed Interfaces:
sealed interface CheckoutState {
    object Idle : CheckoutState
    data class Submitting(val orderId: String) : CheckoutState
    data class Confirmed(val transactionId: String, val receiptUrl: String) : CheckoutState
    data class Failed(val errorReason: String, val canRetry: Boolean) : CheckoutState
}

sealed interface CheckoutEvent {
    data class SubmitClicked(val orderId: String) : CheckoutEvent
    data class PaymentSucceeded(val txId: String, val receipt: String) : CheckoutEvent
    data class PaymentFailed(val reason: String, val canRetry: Boolean) : CheckoutEvent
    object RetryClicked : CheckoutEvent
}

// Reducer نقي يحسب الحالة التالية بناءً على الحالة الحالية والحدث:
fun checkoutReducer(current: CheckoutState, event: CheckoutEvent): CheckoutState = when (current) {
    is CheckoutState.Idle -> when (event) {
        is CheckoutEvent.SubmitClicked -> CheckoutState.Submitting(event.orderId)
        else -> current // تجاهل الأحداث غير القانونية في هذه الحالة
    }
    is CheckoutState.Submitting -> when (event) {
        is CheckoutEvent.PaymentSucceeded -> CheckoutState.Confirmed(event.txId, event.receipt)
        is CheckoutEvent.PaymentFailed -> CheckoutState.Failed(event.reason, event.canRetry)
        else -> current
    }
    is CheckoutState.Failed -> when (event) {
        CheckoutEvent.RetryClicked if current.canRetry -> CheckoutState.Submitting("retry_order")
        else -> current
    }
    is CheckoutState.Confirmed -> current // حالة نهائية، لا تقبل أي انتقالات
}
```

تنفيذ Strategy Pattern مع DI Multibindings لتفادي الـ God Factory:
```kotlin
// 1. العقد الموحد (Strategy Interface):
interface PaymentStrategy {
    val supportedType: PaymentType
    suspend fun pay(orderId: String, amount: Money): PaymentResult
}

// 2. تطبيق مستقل لكل مزود يعزل الـ SDK تماماً (Concrete Strategies):
class StripeStrategy @Inject constructor(
    private val stripeClient: StripeSdkClient
) : PaymentStrategy {
    override val supportedType = PaymentType.STRIPE
    override suspend fun pay(orderId: String, amount: Money): PaymentResult {
        return stripeClient.confirmPayment(orderId, amount.toCents()).toDomain()
    }
}

class GooglePayStrategy @Inject constructor(
    private val paymentsClient: PaymentsClient
) : PaymentStrategy {
    override val supportedType = PaymentType.GOOGLE_PAY
    override suspend fun pay(orderId: String, amount: Money): PaymentResult {
        return paymentsClient.requestPayment(orderId, amount).toDomain()
    }
}

// 3. مدير الدفع النظيف الخالي من الـ God Factory عبر Map Injection:
class PaymentProcessor @Inject constructor(
    private val strategies: Set<@JvmSuppressWildcards PaymentStrategy>
) {
    private val strategyMap: Map<PaymentType, PaymentStrategy> by lazy {
        strategies.associateBy { it.supportedType }
    }

    suspend fun executePayment(type: PaymentType, orderId: String, amount: Money): PaymentResult {
        val strategy = strategyMap[type] 
            ?: throw IllegalArgumentException("Unsupported payment provider: $type")
        return strategy.pay(orderId, amount)
    }
}
```

بناء Anti-Corruption Layer و Adapter لعزل استدعاءات الـ Vendor المختلفة وتحويلها إلى واجهة نقية:
```kotlin
// 1. العقد الصافي في طبقة الـ Domain (لا يعلم شيئاً عن أي Vendor):
interface DocumentScanner {
    suspend fun scanPassport(): Result<PassportData>
}

// 2. Adapter لمزود يعتمد على Callbacks قديمة (Legacy Vendor A):
class VendorAScannerAdapter(private val vendorASdk: LegacyVendorASdk) : DocumentScanner {
    override suspend fun scanPassport(): Result<PassportData> = suspendCancellableCoroutine { continuation ->
        val listener = object : VendorAListener {
            override fun onScanCompleted(vendorModel: VendorADocResult) {
                // تحويل الموديل الخاص بالـ Vendor إلى موديل الدومين النظيف:
                val domainModel = PassportData(vendorModel.docNumber, vendorModel.expiryDate)
                continuation.resume(Result.success(domainModel))
            }
            override fun onScanFailed(errorCode: Int, message: String) {
                continuation.resume(Result.failure(VendorScanException(errorCode, message)))
            }
        }

        vendorASdk.startScan(listener)
        continuation.invokeOnCancellation { vendorASdk.cancel() }
    }
}

// 3. عند التبديل إلى Vendor B، نكتب فقط Adapter جديد بدون لمس أي ViewModel أو UI:
class VendorBScannerAdapter(private val modernVendorB: VendorBClient) : DocumentScanner {
    override suspend fun scanPassport(): Result<PassportData> {
        return runCatching {
            val result = modernVendorB.capture()
            PassportData(result.passportNo, result.validUntil)
        }
    }
}
```

المقارنة بين Global Mutable Object وحامل حالة محقون معزول لكل اختبار:
```kotlin
// ❌ فوضى الـ Global Mutable Singleton: اختبارات ملوثة وتعتمد على الترتيب:
object GlobalUserSession {
    var token: String? = null // متغير عام يلوث الـ JVM Process في كل الاختبارات!
    var userId: String? = null
}

// Test A يغير الحالة:
@Test fun testLogin() {
    GlobalUserSession.token = "token_123"
    assertTrue(AuthManager.isLoggedIn())
}
// Test B يفشل لو اشتغل بعد Test A لأنه يتوقع مستخدم غير مسجل:
@Test fun testLoggedOutState() {
    // سيفشل هنا لأن GlobalUserSession.token لا يزال محتفظاً بقيمة token_123 من Test A!
    assertFalse(AuthManager.isLoggedIn())
}

// ✅ الحل النظيف: كلاس عادي محقون بـ Scoped Ownership عبر Constructor Injection:
interface SessionManager {
    fun getToken(): String?
    fun setToken(token: String?)
}

class DefaultSessionManager @Inject constructor(
    private val storage: KeyValueStorage
) : SessionManager {
    private val _token = MutableStateFlow<String?>(null)
    override fun getToken(): String? = _token.value
    override fun setToken(token: String?) { _token.value = token }
}

// في الـ Tests: كل اختبار ينشئ نسخته المستقلة في @Before، عزل تام 100%:
class AuthManagerTest {
    private lateinit var sessionManager: SessionManager
    private lateinit var authManager: AuthManager

    @Before
    fun setUp() {
        sessionManager = FakeSessionManager() // نسخة جديدة طازجة لكل اختبار!
        authManager = AuthManager(sessionManager)
    }

    @Test fun testLoggedOutState() {
        assertFalse(authManager.isLoggedIn()) // ينجح دائماً بغض النظر عن الترتيب!
    }
}
```

المقارنة بين التعقيد الزائد المتكلف وبين التصميم العملي المباشر:
```kotlin
// ❌ تعقيد غير ضروري (Unnecessary Indirection): 4 طبقات وسيطة لا تفعل شيئاً سوى التمرير!
class GetAppThemeUseCase @Inject constructor(private val repo: ThemeRepository) {
    suspend operator fun invoke(): Theme = repo.getTheme() // مجرد وسيط فارغ!
}
class ThemeRepositoryImpl @Inject constructor(private val facade: ThemeFacade) : ThemeRepository {
    override suspend fun getTheme(): Theme = facade.fetch() // وسيط آخر!
}
class ThemeFacade @Inject constructor(private val adapter: ThemeAdapter) {
    suspend fun fetch(): Theme = adapter.get() // وسيط ثالث!
}

// ✅ تصميم مباشر وعملي (Pragmatic & Clean): ViewModel يتحدث مباشرة إلى Repository:
interface ThemePreferences {
    val isDarkMode: Flow<Boolean>
    suspend fun setDarkMode(enabled: Boolean)
}

@HiltViewModel
class SettingsViewModel @Inject constructor(
    private val themePreferences: ThemePreferences
) : ViewModel() {
    val isDarkMode = themePreferences.isDarkMode.stateIn(
        scope = viewModelScope,
        started = SharingStarted.WhileSubscribed(5000),
        initialValue = false
    )

    fun toggleDarkMode(enabled: Boolean) {
        viewModelScope.launch { themePreferences.setDarkMode(enabled) }
